    struct ParsingRepairProvider {
        calls: AtomicUsize,
    }

    #[async_trait]
    impl ModelProvider for ParsingRepairProvider {
        fn id(&self) -> &str {
            "parsing-repair"
        }

        fn model(&self) -> &str {
            "parsing-repair-v1"
        }

        async fn complete(
            &self,
            request: ModelRequest,
            _cancellation: &CancellationToken,
        ) -> Result<crate::domain::ModelResponse, ProviderError> {
            let call = self.calls.fetch_add(1, Ordering::SeqCst);
            let turn = if call == 0 {
                ModelTurn::InvalidFinal {
                    content: "c\n#include <stdio.h>\nint main(void) { return 0; }".into(),
                    error: "provider answer is not valid AgentAnswer JSON: expected value".into(),
                }
            } else {
                assert!(
                    request
                        .messages
                        .last()
                        .is_some_and(|message| message.content.contains("could not be parsed"))
                );
                assert!(request.tools.is_empty(), "repair must not offer tools");
                assert!(
                    request
                        .messages
                        .iter()
                        .any(|message| message.content.contains("#include <stdio.h>"))
                );
                ModelTurn::Final {
                    answer: AgentAnswer {
                        task_need: None,
                        schema_version: crate::domain::ANSWER_SCHEMA_VERSION,
                        status: AnswerStatus::Completed,
                        conclusion:
                            "C uses #include and main; Python, Java and Rust use their own entry syntax."
                                .into(),
                        claims: Vec::new(),
                        evidence: Vec::new(),
                        assumptions: Vec::new(),
                        constraints: Vec::new(),
                        unknowns: Vec::new(),
                        conflicts: Vec::new(),
                        flip_conditions: Vec::new(),
                        action_receipts: Vec::new(),
                    },
                }
            };
            Ok(crate::domain::ModelResponse {
                provider_id: self.id().into(),
                model: self.model().into(),
                turn,
                usage: Usage::default(),
            })
        }
    }

    #[async_trait]
    impl ModelProvider for NonRetryableFailureProvider {
        fn id(&self) -> &str {
            "unauthorized"
        }

        fn model(&self) -> &str {
            "unauthorized-v1"
        }

        async fn complete(
            &self,
            _request: ModelRequest,
            _cancellation: &CancellationToken,
        ) -> Result<crate::domain::ModelResponse, ProviderError> {
            self.calls.fetch_add(1, Ordering::SeqCst);
            Err(ProviderError {
                code: ProviderErrorCode::Authentication,
                message: format!("auth\u{202e}{}", "x".repeat(1_000)),
                retryable: false,
            })
        }
    }

    #[test]
    fn unresolved_conflict_resolution_fields_are_normalized() {
        let mut answer = AgentAnswer {
            schema_version: 2,
            status: AnswerStatus::NeedsEvidence,
            conclusion: "conflict".into(),
            claims: Vec::new(),
            evidence: Vec::new(),
            assumptions: Vec::new(),
            constraints: Vec::new(),
            unknowns: Vec::new(),
            conflicts: vec![ConflictRecord {
                id: "cf1".into(),
                claim_ids: ["a".into(), "b".into()],
                status: ConflictStatus::Unresolved,
                resolution: Some("explanation".into()),
                resolution_sources: vec!["source".into()],
                resolution_claim_ids: vec!["a".into()],
            }],
            flip_conditions: Vec::new(),
            action_receipts: Vec::new(),
            task_need: None,
        };
        normalize_unresolved_conflicts(&mut answer);
        let conflict = &answer.conflicts[0];
        assert!(conflict.resolution.is_none());
        assert!(conflict.resolution_sources.is_empty());
        assert!(conflict.resolution_claim_ids.is_empty());
    }

