    struct EscalatingChatProvider {
        calls: AtomicUsize,
        requests: Arc<Mutex<Vec<ModelRequest>>>,
    }

    #[async_trait]
    impl ModelProvider for EscalatingChatProvider {
        fn id(&self) -> &str {
            "escalating-chat"
        }

        fn model(&self) -> &str {
            "escalating-chat-v1"
        }

        async fn complete(
            &self,
            request: ModelRequest,
            _cancellation: &CancellationToken,
        ) -> Result<ModelResponse, ProviderError> {
            self.requests.lock().unwrap().push(request);
            let call = self.calls.fetch_add(1, Ordering::SeqCst);
            let (status, conclusion) = if call == 0 {
                (AnswerStatus::NeedsEvidence, "缺少实时信息")
            } else {
                (AnswerStatus::Completed, "完整回答")
            };
            Ok(ModelResponse {
                provider_id: self.id().into(),
                model: self.model().into(),
                turn: ModelTurn::Final {
                    answer: AgentAnswer {
                        task_need: None,
                        schema_version: crate::domain::ANSWER_SCHEMA_VERSION,
                        status,
                        conclusion: conclusion.into(),
                        claims: Vec::new(),
                        evidence: Vec::new(),
                        assumptions: Vec::new(),
                        constraints: Vec::new(),
                        unknowns: Vec::new(),
                        conflicts: Vec::new(),
                        flip_conditions: Vec::new(),
                        action_receipts: Vec::new(),
                    },
                },
                usage: Usage::default(),
            })
        }
    }

